set local lock_timeout='5s';

-- Generated from atlas-login.js rules; do not maintain another canonicalizer.
create or replace function atlas_account_private.visible_login_name(value text) returns text
language plpgsql immutable set search_path='' as $$
declare result text;
begin
  result:=btrim(regexp_replace(normalize(value,NFKC),'[	-    -     　﻿]+',' ','g'));
  if result is null or length(result) not between 2 and 60 or position('@' in result)>0 then
    raise exception 'LOGIN_NAME_INVALID' using errcode='22023'; end if;
  return result;
end $$;
create or replace function atlas_account_private.login_key(value text) returns text
language plpgsql immutable set search_path='' as $$
declare folded text; result text;
begin
  folded:=regexp_replace(normalize(atlas_account_private.visible_login_name(value),NFKD),'[̀-ͯ]','','g');
  if folded !~ '^[A-Za-z0-9 ._-]+$' then raise exception 'LOGIN_NAME_INVALID' using errcode='22023'; end if;
  result:=replace(translate(folded,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'),' ','');
  if result !~ '^[a-z0-9._-]{2,48}$' then raise exception 'LOGIN_KEY_INVALID' using errcode='22023'; end if;
  return result;
end $$;
revoke all on function atlas_account_private.visible_login_name(text), atlas_account_private.login_key(text) from public,anon,authenticated;
-- Include legacy email keys without changing any existing account. The index
-- serializes concurrent claims even before assignment metadata arrives.
create table atlas_account_private.login_keys (
  login_key text primary key,
  user_id uuid not null unique references auth.users(id) on delete cascade deferrable initially deferred
);
alter table atlas_account_private.login_keys enable row level security;
revoke all on atlas_account_private.login_keys from public,anon,authenticated;
insert into atlas_account_private.login_keys(login_key,user_id)
  select lower(split_part(email,'@',1)),id from auth.users
  where deleted_at is null and lower(email) like '%@users.atlas.invalid';
create or replace function atlas_account_private.reserve_login_key() returns trigger
language plpgsql security definer set search_path='' as $$
declare proposed text;
begin
  if new.deleted_at is null and lower(new.email) like '%@users.atlas.invalid' then proposed:=lower(split_part(new.email,'@',1)); end if;
  delete from atlas_account_private.login_keys where user_id=new.id and login_key is distinct from proposed;
  if proposed is not null then
    insert into atlas_account_private.login_keys(login_key,user_id) values(proposed,new.id) on conflict(login_key) do nothing;
    if not exists(select 1 from atlas_account_private.login_keys where login_key=proposed and user_id=new.id) then
      raise exception 'LOGIN_KEY_COLLISION' using errcode='23505';
    end if;
  end if;
  return new;
end $$;
revoke all on function atlas_account_private.reserve_login_key() from public,anon,authenticated;
create trigger atlas_reserve_login_key before insert or update of email,deleted_at on auth.users
  for each row execute function atlas_account_private.reserve_login_key();


CREATE OR REPLACE FUNCTION atlas_account_private.prepare_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  request jsonb; previous_revision bigint := 0; expected_revision bigint;
  home_code text; target_role text; login_name text; login_key text; display_name text;
  actor uuid; operation uuid; allowed_codes text[]; known_roles text[];
begin
  request := new.raw_app_meta_data->'atlas_assignment_request';
  if tg_op='UPDATE' then
    previous_revision := coalesce((old.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0);
  end if;
  if request is null or request='null'::jsonb then
    -- Email may change before app_metadata within one Auth transaction.
    -- The deferred consistency trigger validates the final identity at commit.
    if tg_op='UPDATE' and previous_revision>0 and new.deleted_at is null and
      (new.raw_app_meta_data - array['provider','providers']) is distinct from
      (old.raw_app_meta_data - array['provider','providers']) then
      -- Unrelated metadata may change; authorization fields may not bypass this protocol.
      if row(new.raw_app_meta_data->'role',new.raw_app_meta_data->'atlas_role',
          new.raw_app_meta_data->'roles',new.raw_app_meta_data->'login_name',new.raw_app_meta_data->'login_key',new.raw_app_meta_data->'warehouse_code',
          new.raw_app_meta_data->'home_warehouse_code',new.raw_app_meta_data->'warehouse_access',
          new.raw_app_meta_data->'atlas_assignment_revision')
        is distinct from row(old.raw_app_meta_data->'role',old.raw_app_meta_data->'atlas_role',
          old.raw_app_meta_data->'roles',old.raw_app_meta_data->'login_name',old.raw_app_meta_data->'login_key',old.raw_app_meta_data->'warehouse_code',
          old.raw_app_meta_data->'home_warehouse_code',old.raw_app_meta_data->'warehouse_access',
          old.raw_app_meta_data->'atlas_assignment_revision') then
        raise exception 'ASSIGNMENT_PROTOCOL_REQUIRED' using errcode='23514';
      end if;
    end if;
    return new;
  end if;
  if jsonb_typeof(request)<>'object' then raise exception 'ASSIGNMENT_REQUEST_INVALID' using errcode='23514'; end if;
  actor := (request->>'actor_id')::uuid;
  operation := (request->>'operation_id')::uuid;
  if actor is null or operation is null then raise exception 'ASSIGNMENT_ACTOR_OPERATION_REQUIRED' using errcode='23514'; end if;
  perform 1 from auth.users u join public.profiles p on p.user_id=u.id
    where u.id=actor and u.deleted_at is null and p.role='admin'
      and (u.banned_until is null or u.banned_until<=now())
      and (u.raw_app_meta_data->>'role' in ('admin','administrator')
        or u.raw_app_meta_data->>'atlas_role' in ('admin','administrator')) for share of u,p;
  if not found then
    raise exception 'ADMINISTRATOR_REQUIRED' using errcode='42501';
  end if;
  expected_revision := (request->>'expected_revision')::bigint;
  if expected_revision is null or expected_revision<>previous_revision then
    raise exception 'ASSIGNMENT_REVISION_CONFLICT' using errcode='40001';
  end if;
  home_code := upper(trim(request->>'warehouse_code'));
  target_role := lower(trim(request->>'role'));
  login_name := atlas_account_private.visible_login_name(request->>'login_name');
  login_key := atlas_account_private.login_key(login_name);
  if request ? 'login_key' and login_key is distinct from request->>'login_key' then raise exception 'LOGIN_KEY_INVALID' using errcode='22023'; end if;
  display_name := trim(request->>'display_name');
  if target_role is null or target_role not in ('picker','supervisor','office_receiver','admin') then
    raise exception 'ATLAS_ROLE_INVALID' using errcode='23514'; end if;
  if lower(new.email) is distinct from login_key||'@users.atlas.invalid' then
    raise exception 'LOGIN_NAME_INVALID' using errcode='23514'; end if;
  if display_name is null or length(display_name) not between 1 and 60 then
    raise exception 'DISPLAY_NAME_REQUIRED' using errcode='23514'; end if;
  if target_role='office_receiver' and (home_code not in ('CA','TX') or login_name is distinct from home_code||' COC Receiver' or display_name is distinct from login_name) then
    raise exception 'RECEIVER_IDENTITY_MISMATCH' using errcode='22023';
  end if;
  if exists(select 1 from auth.users u where u.id<>new.id and u.deleted_at is null
    and lower(u.email)=login_key||'@users.atlas.invalid') then
    raise exception 'LOGIN_KEY_COLLISION' using errcode='23505';
  end if;
  lock table public.warehouses in share mode;
  if home_code is null or not exists(select 1 from public.warehouses where code=home_code and active) then
    raise exception 'WAREHOUSE_REQUIRED_OR_INVALID' using errcode='23514'; end if;
  select array_agg(code order by code) into allowed_codes from public.warehouses
    where active and (target_role='admin' or code=home_code);
  insert into atlas_account_private.operations(operation_id,user_id,actor_id,revision)
    values(operation,new.id,actor,previous_revision+1);
  new.raw_app_meta_data := (coalesce(new.raw_app_meta_data,'{}')-'atlas_assignment_request')
    || jsonb_build_object('role',target_role,'atlas_role',target_role,'login_name',login_name,'login_key',login_key,
      'warehouse_code',home_code,'home_warehouse_code',home_code,
      'warehouse_access',to_jsonb(allowed_codes),'atlas_assignment_revision',previous_revision+1,
      'atlas_assignment_operation_id',operation,'atlas_assignment_actor_id',actor);
  if new.raw_app_meta_data ? 'roles' then
    select coalesce(array_agg(value),'{}') into known_roles from jsonb_array_elements_text(new.raw_app_meta_data->'roles')
      where lower(value) not in ('picker','supervisor','office','office_receiver','admin','administrator');
    new.raw_app_meta_data := new.raw_app_meta_data || jsonb_build_object('roles',to_jsonb(known_roles||array[target_role]));
  end if;
  new.raw_user_meta_data := coalesce(new.raw_user_meta_data,'{}') || jsonb_build_object('display_name',display_name);
  return new;
exception when others then
  raise log 'ATLAS_ASSIGNMENT_FAILED category=% sqlstate=%',
    case when SQLERRM in ('ASSIGNMENT_PROTOCOL_REQUIRED','ASSIGNMENT_REVISION_CONFLICT','ACCOUNT_ASSIGNMENT_INCONSISTENT','LOGIN_NAME_INVALID','LOGIN_KEY_INVALID','LOGIN_KEY_COLLISION','RECEIVER_IDENTITY_MISMATCH','ADMINISTRATOR_REQUIRED','WAREHOUSE_REQUIRED_OR_INVALID') then SQLERRM else 'DATABASE_TRANSACTION_FAILED' end, SQLSTATE;
  raise;
end $function$;

CREATE OR REPLACE FUNCTION atlas_account_private.check_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare subject uuid; u auth.users; p public.profiles; actual text[]; expected text[];
begin
  if tg_table_schema<>'auth' then
    if tg_op='UPDATE' and old.user_id<>new.user_id then
      raise exception 'ACCOUNT_OWNERSHIP_IMMUTABLE' using errcode='23514';
    end if;
  end if;
  if tg_table_schema='auth' then subject:=coalesce(new.id,old.id);
  else subject:=coalesce(new.user_id,old.user_id); end if;
  select * into u from auth.users where id=subject for no key update;
  if not found or u.deleted_at is not null or coalesce((u.raw_app_meta_data->>'atlas_assignment_revision')::bigint,0)=0 then return null; end if;
  if lower(u.email) is distinct from coalesce(u.raw_app_meta_data->>'login_key',u.raw_app_meta_data->>'login_name')||'@users.atlas.invalid' then
    raise exception 'ASSIGNMENT_PROTOCOL_REQUIRED' using errcode='23514';
  end if;
  if u.raw_app_meta_data ? 'login_key' and u.raw_app_meta_data->>'login_key' is distinct from atlas_account_private.login_key(u.raw_app_meta_data->>'login_name') then
    raise exception 'LOGIN_KEY_INVALID' using errcode='23514';
  end if;
  select * into p from public.profiles where user_id=subject;
  if not found or p.role::text is distinct from (case when u.raw_app_meta_data->>'role'='office_receiver' then 'picker' else u.raw_app_meta_data->>'role' end)
    or not exists(select 1 from public.warehouses where id=p.warehouse_id and code=u.raw_app_meta_data->>'home_warehouse_code') then
    raise exception 'ACCOUNT_ASSIGNMENT_INCONSISTENT' using errcode='23514';
  end if;
  select coalesce(array_agg(w.code order by w.code),'{}') into actual
    from public.profile_warehouse_access a join public.warehouses w on w.id=a.warehouse_id where a.user_id=subject;
  select coalesce(array_agg(value order by value),'{}') into expected
    from jsonb_array_elements_text(u.raw_app_meta_data->'warehouse_access');
  if actual is distinct from expected then raise exception 'ACCOUNT_ASSIGNMENT_INCONSISTENT' using errcode='23514'; end if;
  -- An UPDATE moving the ownership key must check the old owner too.

  return null;
exception when others then
  raise log 'ATLAS_ASSIGNMENT_FAILED category=% sqlstate=%',
    case when SQLERRM in ('ASSIGNMENT_PROTOCOL_REQUIRED','ASSIGNMENT_REVISION_CONFLICT','ACCOUNT_ASSIGNMENT_INCONSISTENT','LOGIN_NAME_INVALID','LOGIN_KEY_INVALID','LOGIN_KEY_COLLISION','RECEIVER_IDENTITY_MISMATCH','ADMINISTRATOR_REQUIRED','WAREHOUSE_REQUIRED_OR_INVALID') then SQLERRM else 'DATABASE_TRANSACTION_FAILED' end, SQLSTATE;
  raise;
end $function$;

CREATE OR REPLACE FUNCTION atlas_account_private.capture_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update atlas_account_private.operations set request=jsonb_build_object(
    'role',new.raw_app_meta_data->>'role',
    'warehouse_code',new.raw_app_meta_data->>'home_warehouse_code',
    'login_name',new.raw_app_meta_data->>'login_name',
    'login_key',new.raw_app_meta_data->>'login_key',
    'display_name',new.raw_user_meta_data->>'display_name')
    where operation_id=(new.raw_app_meta_data->>'atlas_assignment_operation_id')::uuid and request is null;
  return new;
end $function$;

